<?php  $evs=$eventos;  ?>
<p class="lead">Administra la programación, los precios y el aforo de tus eventos.</p><details class="card editor" <?= $edit || isset($_GET['nuevo'])?'open':'' ?>><summary><?= $edit?'Editar evento':'Crear evento' ?></summary><form method="post" class="form-grid"><?= csrf() ?><input type="hidden" name="action" value="save_event"><input type="hidden" name="id" value="<?= e($edit['id_evento']??'') ?>"><label>Nombre del evento<input name="nombre" maxlength="100" value="<?= e($edit['nombre']??'') ?>" required></label><label>Categoría<select name="categoria"><?php foreach(['Concierto','Teatro','Deportivo','Conferencia','Otro'] as $cat): ?><option <?= ($edit['categoria']??'Concierto')===$cat?'selected':'' ?>><?= e($cat) ?></option><?php endforeach ?></select></label><label>Fecha<input type="date" name="fecha" value="<?= e($edit['fecha']??date('Y-m-d')) ?>" required></label><label>Precio (USD)<input type="number" name="precio" min="0" max="10000" step="0.01" value="<?= e($edit['precio']??'10.00') ?>" required></label><label>Aforo<input type="number" name="aforo" min="1" max="100000" value="<?= e($edit['aforo']??'100') ?>" required></label><label class="check"><input type="checkbox" name="activo" value="1" <?= ($edit['activo']??1)?'checked':'' ?>>Evento activo</label><label class="span-all">Descripción<textarea name="descripcion" maxlength="255" rows="3"><?= e($edit['descripcion']??'') ?></textarea></label><div class="form-actions span-all"><button class="button">Guardar evento</button><a class="button secondary" href="<?= e(url('eventos')) ?>">Cancelar</a></div></form></details>
<div class="card table-wrap"><table><caption><?= count($evs) ?> eventos registrados</caption><thead><tr><th>Evento</th><th>Categoría</th><th>Fecha</th><th>Precio</th><th>Aforo ocupado</th><th>Estado</th><th>Acciones</th></tr></thead><tbody><?php foreach($evs as $ev): ?><tr><td><strong><?= e($ev['nombre']) ?></strong></td><td><?= e($ev['categoria']) ?></td><td><?= dateLabel($ev['fecha']) ?></td><td><?= money($ev['precio']) ?></td><td><?= $ev['vendidas'] ?> / <?= $ev['aforo'] ?></td><td><span class="badge <?= $ev['activo']?'DISPONIBLE':'ANULADA' ?>"><?= $ev['activo']?'Activo':'Inactivo' ?></span></td><td class="actions"><a class="button small secondary" href="<?= e(url('eventos',['edit'=>$ev['id_evento']])) ?>">Editar</a><?php actionForm('delete_event',(int)$ev['id_evento'],'Eliminar','¿Eliminar este evento? Solo se permite si no tiene boletos registrados.'); ?></td></tr><?php endforeach; if(!$evs): ?><tr><td colspan="7" class="empty">Todavía no hay eventos.</td></tr><?php endif ?></tbody></table></div>
